        }

        Map<Id, npsp__DataImport__c> processedById =
            new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :dataImportIds
            ]);

        for (Integer j = 0; j < dataImports.size(); j++) {
            Integer giftIndex = dataImportGiftIndexes[j];
            npsp__DataImport__c processed = processedById.get(dataImports[j].Id);
            ImportResult result = results[giftIndex];

            if (processed != null &&
                String.isNotBlank(processed.npsp__Status__c) &&
                processed.npsp__Status__c.equalsIgnoreCase('Imported')) {
                result.success = true;
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
                result.errorMessage = null;
            } else {
                result.success = false;
                result.contactId = null;
                result.opportunityId = null;
                if (processed != null &&
                    String.isNotBlank(processed.npsp__FailureInformation__c)) {
                    result.errorMessage = processed.npsp__FailureInformation__c;
                } else if (String.isNotBlank(processError)) {
                    result.errorMessage = processError;
                } else if (processed != null &&
                           String.isNotBlank(processed.npsp__Status__c)) {
                    result.errorMessage =
                        'NPSP Data Import failed with status: ' +
                        processed.npsp__Status__c;
                } else {
                    result.errorMessage = 'NPSP Data Import did not import this row.';
                }
            }
        }

        return results;
    }
